[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>WellSource — Expert health guidance you can trust</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --teal: #02838D;
      --teal-dark: #016870;
      --teal-light: #e6f5f6;
      --teal-mid: #b3dde0;
      --charcoal: #231F20;
      --gray-700: #374151;
      --gray-500: #6B7280;
      --gray-300: #D1D5DB;
      --gray-100: #F3F4F6;
      --gray-50: #F9FAFB;
      --white: #FFFFFF;
      --coral: #E8634A;
      --coral-dark: #d0533a;
      --amber: #F59E0B;
      --radius: 12px;
      --radius-sm: 8px;
      --shadow: 0 2px 12px rgba(0,0,0,0.08);
      --shadow-md: 0 4px 24px rgba(0,0,0,0.12);
    }

    body {
      font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;
      color: var(--charcoal);
      background: var(--white);
      line-height: 1.6;
      overflow-x: hidden;
    }

    a { color: inherit; text-decoration: none; }
    img { display: block; max-width: 100%; }
    button { cursor: pointer; font-family: inherit; border: none; background: none; }

    /* ========== UTILITY ========== */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .section-heading {
      font-size: 1.75rem;
      font-weight: 700;
      color: var(--charcoal);
      margin-bottom: 24px;
    }
    .view-all {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      color: var(--teal);
      font-weight: 600;
      font-size: 0.9rem;
      transition: gap 0.2s;
    }
    .view-all:hover { gap: 10px; }
    .view-all::after { content: '→'; }

    /* ========== TOP NAV BAR ========== */
    .top-bar {
      background: var(--teal);
      color: var(--white);
      font-size: 0.78rem;
      font-weight: 500;
      padding: 6px 0;
      text-align: center;
      letter-spacing: 0.02em;
    }

    /* ========== HEADER ========== */
    header {
      background: var(--white);
      border-bottom: 1px solid var(--gray-100);
      position: sticky;
      top: 0;
      z-index: 1000;
      box-shadow: 0 1px 8px rgba(0,0,0,0.06);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 68px;
      gap: 24px;
    }

    .logo {
      font-size: 1.5rem;
      font-weight: 700;
      color: var(--teal);
      flex-shrink: 0;
      letter-spacing: -0.03em;
    }
    .logo span { color: var(--charcoal); }

    /* Main Nav */
    .main-nav { display: flex; align-items: center; gap: 4px; flex: 1; justify-content: center; }

    .nav-item {
      position: relative;
    }

    .nav-trigger {
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 8px 14px;
      font-size: 0.9rem;
      font-weight: 600;
      color: var(--charcoal);
      border-radius: var(--radius-sm);
      transition: background 0.15s, color 0.15s;
      white-space: nowrap;
    }
    .nav-trigger:hover, .nav-item.open .nav-trigger {
      background: var(--teal-light);
      color: var(--teal);
    }
    .nav-trigger .chevron {
      width: 14px; height: 14px;
      transition: transform 0.2s;
    }
    .nav-item.open .chevron { transform: rotate(180deg); }

    /* Mega Menu */
    .mega-menu {
      position: absolute;
      top: calc(100% + 10px);
      left: 50%;
      transform: translateX(-50%);
      background: var(--white);
      border: 1px solid var(--gray-100);
      border-radius: var(--radius);
      box-shadow: var(--shadow-md);
      padding: 28px 32px;
      min-width: 480px;
      opacity: 0;
      visibility: hidden;
      transition: opacity 0.18s, transform 0.18s;
      transform: translateX(-50%) translateY(-6px);
      pointer-events: none;
    }
    .nav-item.open .mega-menu {
      opacity: 1;
      visibility: visible;
      transform: translateX(-50%) translateY(0);
      pointer-events: all;
    }

    .mega-menu-title {
      font-size: 0.7rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--gray-500);
      margin-bottom: 16px;
    }

    .mega-menu-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 6px 20px;
    }
    .mega-menu-grid.cols-2 { grid-template-columns: repeat(2, 1fr); }

    .mega-menu-grid a {
      font-size: 0.875rem;
      color: var(--gray-700);
      padding: 4px 0;
      border-bottom: 1px solid transparent;
      transition: color 0.15s, border-color 0.15s;
    }
    .mega-menu-grid a:hover { color: var(--teal); border-bottom-color: var(--teal-mid); }

    .mega-menu-divider { border: none; border-top: 1px solid var(--gray-100); margin: 20px 0; }

    .mega-menu-feature {
      display: flex;
      gap: 24px;
    }
    .mega-menu-col { flex: 1; }
    .mega-menu-col-title {
      font-size: 0.7rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--teal);
      margin-bottom: 10px;
    }

    /* Header actions */
    .header-actions {
      display: flex;
      align-items: center;
      gap: 10px;
      flex-shrink: 0;
    }
    .btn-outline {
      padding: 7px 18px;
      border: 2px solid var(--teal);
      color: var(--teal);
      border-radius: 50px;
      font-size: 0.875rem;
      font-weight: 600;
      transition: background 0.15s, color 0.15s;
    }
    .btn-outline:hover { background: var(--teal); color: var(--white); }
    .btn-solid {
      padding: 7px 18px;
      background: var(--teal);
      color: var(--white);
      border-radius: 50px;
      font-size: 0.875rem;
      font-weight: 600;
      transition: background 0.15s;
    }
    .btn-solid:hover { background: var(--teal-dark); }

    /* ========== TICKER ========== */
    .ticker-bar {
      background: var(--charcoal);
      color: var(--white);
      padding: 10px 0;
      overflow: hidden;
    }

    .ticker-track {
      display: flex;
      width: max-content;
      animation: ticker-scroll 22s linear infinite;
    }

    .ticker-item {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 0 48px;
      font-size: 0.82rem;
      font-weight: 500;
      white-space: nowrap;
    }

    .ticker-item .ticker-dot {
      width: 6px; height: 6px;
      background: var(--teal);
      border-radius: 50%;
      flex-shrink: 0;
    }
    .ticker-item strong { color: var(--teal); }

    @keyframes ticker-scroll {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    /* ========== HERO ========== */
    .hero {
      background: linear-gradient(135deg, #f0fafb 0%, #e6f5f6 60%, #fef3f0 100%);
      padding: 60px 0 56px;
    }

    .hero-inner {
      display: grid;
      grid-template-columns: 1fr 340px;
      gap: 48px;
      align-items: center;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--teal);
      color: var(--white);
      font-size: 0.75rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      padding: 5px 14px;
      border-radius: 50px;
      margin-bottom: 20px;
    }

    .hero-tag {
      display: inline-block;
      color: var(--teal);
      font-size: 0.8rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      margin-bottom: 12px;
    }

    .hero h1 {
      font-size: 2.6rem;
      font-weight: 700;
      line-height: 1.15;
      color: var(--charcoal);
      margin-bottom: 18px;
      letter-spacing: -0.02em;
    }

    .hero-sub {
      font-size: 1.1rem;
      color: var(--gray-500);
      max-width: 560px;
      margin-bottom: 28px;
      line-height: 1.65;
    }

    .btn-hero {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--coral);
      color: var(--white);
      padding: 14px 30px;
      border-radius: 50px;
      font-size: 1rem;
      font-weight: 700;
      transition: background 0.15s, transform 0.15s;
      box-shadow: 0 4px 16px rgba(232,99,74,0.3);
    }
    .btn-hero:hover { background: var(--coral-dark); transform: translateY(-1px); }
    .btn-hero::after { content: '→'; }

    .hero-visual {
      position: relative;
    }

    .hero-card {
      background: var(--white);
      border-radius: 20px;
      box-shadow: var(--shadow-md);
      overflow: hidden;
    }

    .hero-card-img {
      height: 200px;
      background: linear-gradient(135deg, #02838D 0%, #016870 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 4rem;
    }

    .hero-card-body { padding: 20px; }
    .hero-card-body .tag {
      font-size: 0.72rem;
      font-weight: 700;
      color: var(--teal);
      text-transform: uppercase;
      letter-spacing: 0.08em;
      margin-bottom: 8px;
    }
    .hero-card-body h3 {
      font-size: 1rem;
      font-weight: 700;
      line-height: 1.4;
      margin-bottom: 10px;
    }
    .hero-card-body .meta {
      font-size: 0.78rem;
      color: var(--gray-500);
      display: flex;
      align-items: center;
      gap: 6px;
    }
    .hero-card-body .meta::before { content: '✓'; color: var(--teal); font-weight: 700; }

    .challenge-badge {
      position: absolute;
      top: -12px;
      right: -12px;
      background: var(--amber);
      color: var(--white);
      font-size: 0.72rem;
      font-weight: 700;
      padding: 8px 14px;
      border-radius: 50px;
      box-shadow: 0 2px 10px rgba(245,158,11,0.4);
      transform: rotate(3deg);
    }

    /* ========== TRENDING ========== */
    .trending { padding: 52px 0; background: var(--white); }

    .trending-inner {
      display: grid;
      grid-template-columns: 1fr 320px;
      gap: 48px;
    }

    .trending-list { display: flex; flex-direction: column; gap: 0; }

    .trending-item {
      display: flex;
      gap: 20px;
      align-items: flex-start;
      padding: 20px 0;
      border-bottom: 1px solid var(--gray-100);
      transition: background 0.15s;
    }
    .trending-item:last-child { border-bottom: none; }

    .trending-num {
      font-size: 2rem;
      font-weight: 700;
      color: var(--teal-mid);
      line-height: 1;
      min-width: 36px;
      flex-shrink: 0;
    }

    .trending-content .tag {
      font-size: 0.72rem;
      font-weight: 700;
      color: var(--teal);
      text-transform: uppercase;
      letter-spacing: 0.08em;
      margin-bottom: 6px;
    }

    .trending-content h3 {
      font-size: 1.05rem;
      font-weight: 600;
      line-height: 1.4;
      color: var(--charcoal);
      transition: color 0.15s;
    }
    .trending-item:hover .trending-content h3 { color: var(--teal); }

    /* Trending sidebar */
    .trending-sidebar { display: flex; flex-direction: column; gap: 16px; }

    .sidebar-card {
      background: var(--gray-50);
      border-radius: var(--radius);
      padding: 22px;
      border: 1px solid var(--gray-100);
    }

    .sidebar-card h4 { font-size: 1rem; font-weight: 700; margin-bottom: 8px; }
    .sidebar-card p { font-size: 0.875rem; color: var(--gray-500); line-height: 1.5; margin-bottom: 14px; }

    .btn-teal {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: var(--teal);
      color: var(--white);
      padding: 9px 20px;
      border-radius: 50px;
      font-size: 0.875rem;
      font-weight: 600;
      transition: background 0.15s;
    }
    .btn-teal:hover { background: var(--teal-dark); }

    /* ========== NEWSLETTER CTA ========== */
    .newsletter-cta {
      background: linear-gradient(135deg, var(--teal) 0%, var(--teal-dark) 100%);
      padding: 64px 0;
      position: relative;
      overflow: hidden;
    }
    .newsletter-cta::before {
      content: '';
      position: absolute;
      top: -80px; right: -80px;
      width: 300px; height: 300px;
      background: rgba(255,255,255,0.06);
      border-radius: 50%;
    }
    .newsletter-cta::after {
      content: '';
      position: absolute;
      bottom: -60px; left: -60px;
      width: 240px; height: 240px;
      background: rgba(255,255,255,0.04);
      border-radius: 50%;
    }

    .newsletter-cta-inner {
      position: relative;
      z-index: 1;
      text-align: center;
      max-width: 600px;
      margin: 0 auto;
    }

    .newsletter-cta h2 {
      font-size: 2.2rem;
      font-weight: 700;
      color: var(--white);
      margin-bottom: 14px;
      letter-spacing: -0.02em;
    }

    .newsletter-cta p {
      color: rgba(255,255,255,0.85);
      font-size: 1.05rem;
      margin-bottom: 32px;
      line-height: 1.6;
    }

    .newsletter-form {
      display: flex;
      gap: 10px;
      max-width: 480px;
      margin: 0 auto 14px;
    }

    .newsletter-form input {
      flex: 1;
      padding: 14px 20px;
      border-radius: 50px;
      border: none;
      font-size: 0.95rem;
      font-family: inherit;
      outline: none;
    }
    .newsletter-form input:focus { box-shadow: 0 0 0 3px rgba(255,255,255,0.3); }

    .btn-cta {
      padding: 14px 28px;
      background: var(--coral);
      color: var(--white);
      border-radius: 50px;
      font-size: 0.95rem;
      font-weight: 700;
      white-space: nowrap;
      transition: background 0.15s;
      border: none;
      cursor: pointer;
      font-family: inherit;
    }
    .btn-cta:hover { background: var(--coral-dark); }

    .newsletter-privacy {
      font-size: 0.78rem;
      color: rgba(255,255,255,0.65);
    }

    /* ========== HEALTH TOPICS ========== */
    .health-topics { padding: 60px 0; background: var(--gray-50); }

    .health-topics-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 32px;
    }

    .carousel-wrapper { position: relative; }

    .carousel-track-outer {
      overflow: hidden;
      border-radius: var(--radius);
    }

    .carousel-track {
      display: flex;
      gap: 20px;
      transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    }

    .topic-card {
      flex-shrink: 0;
      width: 140px;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 14px;
      cursor: pointer;
      padding: 12px;
      border-radius: var(--radius);
      transition: background 0.15s;
    }
    .topic-card:hover { background: var(--white); }

    .topic-img {
      width: 100px;
      height: 100px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 2.2rem;
      flex-shrink: 0;
      box-shadow: var(--shadow);
      transition: transform 0.2s;
    }
    .topic-card:hover .topic-img { transform: scale(1.06); }

    .topic-label {
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--charcoal);
      text-align: center;
      line-height: 1.3;
    }

    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 42px; height: 42px;
      background: var(--white);
      border: 1px solid var(--gray-300);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow);
      cursor: pointer;
      z-index: 2;
      transition: background 0.15s, border-color 0.15s;
      font-size: 1rem;
    }
    .carousel-btn:hover { background: var(--teal); border-color: var(--teal); color: var(--white); }
    .carousel-btn.prev { left: -20px; }
    .carousel-btn.next { right: -20px; }

    /* ========== TOOLS ========== */
    .tools-section { padding: 60px 0; background: var(--white); }

    .tools-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 32px;
    }

    /* Nutrition Hub */
    .nutrition-hub {
      background: linear-gradient(135deg, var(--teal-light) 0%, #d0eef0 100%);
      border-radius: 20px;
      padding: 36px;
      display: flex;
      flex-direction: column;
      gap: 20px;
    }

    .nutrition-hub .hub-icon {
      font-size: 2.5rem;
      margin-bottom: 4px;
    }
    .nutrition-hub h3 {
      font-size: 1.5rem;
      font-weight: 700;
      color: var(--charcoal);
      margin-bottom: 8px;
    }
    .nutrition-hub p {
      font-size: 0.9rem;
      color: var(--gray-700);
      line-height: 1.6;
      margin-bottom: 4px;
    }

    .tool-list { display: flex; flex-direction: column; gap: 12px; margin-top: 4px; }

    .tool-item {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      background: rgba(255,255,255,0.7);
      border-radius: var(--radius-sm);
      padding: 14px;
    }
    .tool-item-icon { font-size: 1.4rem; flex-shrink: 0; }
    .tool-item-text strong { display: block; font-size: 0.875rem; font-weight: 700; margin-bottom: 2px; }
    .tool-item-text span { font-size: 0.8rem; color: var(--gray-500); }

    /* Drug & Care Tools */
    .drug-care {
      display: flex;
      flex-direction: column;
      gap: 14px;
    }

    .drug-care-title {
      font-size: 1.2rem;
      font-weight: 700;
      color: var(--charcoal);
      padding-bottom: 12px;
      border-bottom: 2px solid var(--gray-100);
    }

    .drug-tool-card {
      background: var(--gray-50);
      border: 1px solid var(--gray-100);
      border-radius: var(--radius);
      padding: 18px;
      display: flex;
      align-items: flex-start;
      gap: 14px;
      transition: border-color 0.15s, box-shadow 0.15s;
      cursor: pointer;
    }
    .drug-tool-card:hover { border-color: var(--teal); box-shadow: 0 2px 12px rgba(2,131,141,0.1); }

    .drug-tool-icon {
      width: 44px; height: 44px;
      background: var(--teal-light);
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.3rem;
      flex-shrink: 0;
    }

    .drug-tool-text strong { display: block; font-size: 0.9rem; font-weight: 700; margin-bottom: 4px; }
    .drug-tool-text span { font-size: 0.8rem; color: var(--gray-500); }
    .drug-tool-text .tool-link {
      display: inline-block;
      font-size: 0.78rem;
      color: var(--teal);
      font-weight: 600;
      margin-top: 6px;
    }

    /* ========== RECOMMENDED READS ========== */
    .recommended-reads { padding: 60px 0; background: var(--gray-50); }

    .tabs {
      display: flex;
      gap: 6px;
      margin-bottom: 32px;
      flex-wrap: wrap;
    }

    .tab-btn {
      padding: 9px 20px;
      border-radius: 50px;
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--gray-500);
      background: var(--white);
      border: 1px solid var(--gray-300);
      cursor: pointer;
      transition: all 0.15s;
      font-family: inherit;
    }
    .tab-btn:hover { border-color: var(--teal); color: var(--teal); }
    .tab-btn.active {
      background: var(--teal);
      border-color: var(--teal);
      color: var(--white);
    }

    .articles-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .article-card {
      background: var(--white);
      border-radius: var(--radius);
      overflow: hidden;
      border: 1px solid var(--gray-100);
      box-shadow: var(--shadow);
      transition: transform 0.2s, box-shadow 0.2s;
      cursor: pointer;
    }
    .article-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }

    .article-card-img {
      height: 160px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
    }

    .article-card-body { padding: 18px; }
    .article-card-body .tag {
      font-size: 0.7rem;
      font-weight: 700;
      color: var(--teal);
      text-transform: uppercase;
      letter-spacing: 0.08em;
      margin-bottom: 8px;
    }
    .article-card-body h4 {
      font-size: 0.975rem;
      font-weight: 700;
      line-height: 1.4;
      color: var(--charcoal);
      margin-bottom: 10px;
    }
    .article-card-body .meta {
      font-size: 0.75rem;
      color: var(--gray-500);
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .reviewed-badge {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      font-size: 0.7rem;
      color: var(--teal);
      font-weight: 600;
    }
    .reviewed-badge::before { content: '✓'; }

    /* ========== TRUST SECTION ========== */
    .trust-section {
      padding: 72px 0;
      background: var(--white);
    }

    .trust-section .section-heading {
      text-align: center;
      max-width: 560px;
      margin: 0 auto 48px;
