    .trust-pillar {
      text-align: center;
      padding: 32px 24px;
      background: var(--gray-50);
      border-radius: 20px;
      border: 1px solid var(--gray-100);
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .trust-pillar:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }

    .pillar-icon {
      width: 60px; height: 60px;
      background: var(--teal-light);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.6rem;
      margin: 0 auto 18px;
    }

    .trust-pillar h3 {
      font-size: 1.05rem;
      font-weight: 700;
      color: var(--charcoal);
      margin-bottom: 10px;
    }
    .trust-pillar p {
      font-size: 0.875rem;
      color: var(--gray-500);
      line-height: 1.6;
    }

    /* ========== FEATURED PROGRAMS ========== */
    .featured-programs { padding: 60px 0; background: var(--gray-50); }

    .section-header-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 28px;
    }

    .programs-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }

    .program-card {
      background: var(--white);
      border-radius: var(--radius);
      overflow: hidden;
      box-shadow: var(--shadow);
      transition: transform 0.2s, box-shadow 0.2s;
      cursor: pointer;
    }
    .program-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }

    .program-card-img {
      height: 130px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 2.5rem;
    }

    .program-card-body {
      padding: 16px;
    }
    .program-card-body .tag {
      font-size: 0.7rem;
      font-weight: 700;
      color: var(--teal);
      text-transform: uppercase;
      letter-spacing: 0.08em;
      margin-bottom: 6px;
    }
    .program-card-body h4 {
      font-size: 0.925rem;
      font-weight: 700;
      line-height: 1.4;
      color: var(--charcoal);
    }

    /* ========== LATEST VIDEOS ========== */
    .latest-videos { padding: 60px 0; background: var(--white); }

    .videos-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }

    .video-card {
      border-radius: var(--radius);
      overflow: hidden;
      background: var(--gray-50);
      box-shadow: var(--shadow);
      cursor: pointer;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .video-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }

    .video-card-img {
      height: 140px;
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 2.5rem;
    }

    .play-btn {
      position: absolute;
      width: 48px; height: 48px;
      background: rgba(255,255,255,0.9);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: 0 2px 12px rgba(0,0,0,0.2);
      transition: transform 0.15s, background 0.15s;
    }
    .video-card:hover .play-btn { background: var(--white); transform: scale(1.1); }

    .play-btn::after {
      content: '';
      display: block;
      width: 0; height: 0;
      border-style: solid;
      border-width: 8px 0 8px 16px;
      border-color: transparent transparent transparent var(--teal);
      margin-left: 3px;
    }

    .video-duration {
      position: absolute;
      bottom: 8px;
      right: 10px;
      background: rgba(0,0,0,0.65);
      color: var(--white);
      font-size: 0.72rem;
      font-weight: 600;
      padding: 2px 7px;
      border-radius: 4px;
