      padding: 24px 0;
    }

    .footer-bottom-inner {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 24px;
      flex-wrap: wrap;
    }

    .footer-links {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
      margin-bottom: 12px;
    }

    .footer-links a {
      font-size: 0.78rem;
      color: rgba(255,255,255,0.5);
      transition: color 0.15s;
    }
    .footer-links a:hover { color: var(--white); }

    .footer-legal {
      font-size: 0.75rem;
      color: rgba(255,255,255,0.35);
      line-height: 1.6;
      max-width: 680px;
    }

    .social-links {
