      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 0.85rem;
      color: rgba(255,255,255,0.7);
      transition: background 0.15s, color 0.15s;
      cursor: pointer;
    }
    .social-btn:hover { background: var(--teal); color: var(--white); }

    /* ========== OVERLAY ========== */
